<?php
declare(strict_types=1);
require_once __DIR__ . '/../../app/bootstrap.php'; require_once __DIR__ . '/../../app/operational_writes.php';require_operation_post('DOCUMENTOS_REGISTRAR');try{$request=operation_id($_POST['solicitud_id']??null);$type=operation_id($_POST['tipo_documento_id']??null);$reference=operation_text($_POST['numero_referencia']??null,100);$url=operation_reference_url($_POST['archivo_url']??null);}catch(InvalidArgumentException $exception){operation_error($exception->getMessage());}try{$stmt=db()->prepare('DECLARE @documento_id INT; EXEC dbo.sp_registrar_documento @solicitud_id=?,@tipo_documento_id=?,@numero_referencia=?,@archivo_url=?,@documento_id=@documento_id OUTPUT;');$stmt->execute([$request,$type,$reference,$url]);$stmt->closeCursor();}catch(PDOException $exception){operation_sql_error($exception,[50406=>'No tienes permiso para registrar documentos.']);}operation_success('Documento registrado correctamente.','documentoRegistrado','/entregas.php?seccion=documentos');
